def _register_existing() -> None:
    """Data step (defect D2): register every existing (symbol, source). A source that holds more than one
    timeframe keeps the timeframe with the most rows as its base; the other timeframes are moved to a separate
    QUARANTINED dataset so they can never again shadow the historical series."""
    from sqlalchemy.orm import Session
    from app.data import store
    from app.models import Dataset
    bind = op.get_bind()
    db = Session(bind=bind)
    groups = bind.execute(sa.text("select symbol, source, timeframe, count(*) from candles group by 1, 2, 3")).all()
    by_ds: dict = {}
    for sym, src, tf, n in groups:
        by_ds.setdefault((sym, src), []).append((n, tf))
    for (sym, src), tfs in by_ds.items():
        tfs.sort(reverse=True)
        base_tf = tfs[0][1]
        kind = store.kind_for_source(src)
        prov = {"registered_by": "migration 0002"}
        if kind == "quarantined":
            prov["quarantine_reason"] = "re-registered quarantined dataset (name ends in -quarantined)"
        ds = Dataset(symbol=sym, source=src, base_timeframe=base_tf, kind=kind,
                     calendar=store.calendar_for(sym), provenance=prov, split={})
        db.add(ds)
        db.flush()
        store.refresh_registry(db, ds)
        for n, tf in tfs[1:]:
            q_src = f"{src}-{tf}"[:48 - len(store.QUARANTINE_SUFFIX)] + store.QUARANTINE_SUFFIX
            bind.execute(sa.text("update candles set source = :q where symbol = :s and source = :src and timeframe = :tf"),
                         {"q": q_src, "s": sym, "src": src, "tf": tf})
            qd = Dataset(symbol=sym, source=q_src, base_timeframe=tf, kind="quarantined", calendar=store.calendar_for(sym),
                         provenance={"registered_by": "migration 0002", "original_source": src,
                                     "quarantine_reason": f"{n} {tf} rows were stored in source '{src}' alongside its "
                                                          f"{base_tf} history and shadowed it (defect D2)"}, split={})
            db.add(qd)
            db.flush()
            store.refresh_registry(db, qd)
    db.flush()


